def test_ops3():
    assert close(vals(s.agg(["sum", "mean", "max", "min", "std", "count", "median"])), E_agg_s)
    assert [str(x) for x in (s.agg(["sum", "mean", "max"]).index).tolist()] == E_agg_s_i
    assert close([s.agg("var")], E_agg_one)
    assert close(fvals(dn.agg(["sum", "mean", "min"])), E_agg_d)
    assert close(vals(dn.agg("max")), E_agg_d1)
    assert close(vals(s.describe([0.1, 0.9])), E_desc_p)
    assert [str(x) for x in (s.describe([0.1, 0.9]).index).tolist()] == E_desc_p_i
    assert close(fvals(d.describe([0.05, 0.5])), E_desc_d)
    assert [str(x) for x in (d.describe().columns).tolist()] == E_desc_dc
    da = d.describe(None, "all")
    assert [str(x) for x in da.index.tolist()] == E_desc_all
    assert [str(x) for x in da.columns.tolist()] == E_desc_allc
    assert close(vals(d.describe(None, "all")["h"]), E_desc_all_h)
    assert [str(x) for x in d.describe(None, "all")["t"].tolist()] == E_desc_all_t
    assert close(vals(d.nlargest(4, "h")["h"]), E_nlarg_h)
    assert [str(x) for x in (d.nlargest(4, "h").index).tolist()] == E_nlarg_i
    assert [str(x) for x in (d.nsmallest(5, ["k", "h"]).index).tolist()] == E_nsmall_i
    assert [str(x) for x in (s.nlargest(3).index).tolist()] == E_nlarg_s
    assert [str(x) for x in (s.nsmallest(3).index).tolist()] == E_nsmall_s
    assert close(vals(s.rank(pct=True)), E_rank_pct)
    assert close(vals(s.rank("dense", True, "keep", True)), E_rank_pct2)
    assert close(vals(s.clip(0.5, 3.0)), E_clip)
    assert close(vals(s.clip(lower=1.0)), E_clip_lo)
    assert close(vals(s.round(1)), E_round2)
    assert close(vals(s.where(s > 1.5, -1.0)), E_where)
    assert close(vals(s.where(s > 1.5)), E_where_nan)
    assert close(vals(s.mask(s > 1.5, 0.0)), E_mask)
    assert close(vals(s.isin([0.53, 1.06, 3.18])), E_isin)
    assert close(vals(s.between(0.5, 2.5)), E_between)
    assert close(vals(s.between(0.53, 2.5, "left")), E_between_l)
    assert close(vals(s.combine_first(o)), E_cfirst)
    assert [str(x) for x in (s.combine_first(o).index).tolist()] == E_cfirst_i
    assert close(vals(update_case(s)), E_update)
    assert close(vals(s.sample(5, None, False, 3)), E_samp_s)
    assert [str(x) for x in (s.sample(5, None, False, 3).index).tolist()] == E_samp_s_i
    assert [str(x) for x in (d.sample(None, 0.2, False, 11).index).tolist()] == E_samp_f
    assert [str(x) for x in (d.sample(12, None, True, 7).index).tolist()] == E_samp_r
    assert close(vals(d.sample(4, None, False, 1)["h"]), E_samp_d)
test_ops3()
